def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find the separate 8-colored blocks.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 8 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append(cells)

    # The little colored key assigns colors to the blocks in reading order.
    key = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 8):
                key.append((r, c, grid[r][c]))
    key.sort()
    colors = []
    for _, _, color in key:
        if color not in colors:
            colors.append(color)

    comps.sort(key=lambda cells: (min(y for y, x in cells), min(x for y, x in cells)))
    for i, cells in enumerate(comps):
        color = colors[i % len(colors)] if colors else 8
        for y, x in cells:
            out[y][x] = color
    return out
